#!/usr/bin/env python3
"""Prepare complete author metadata for the GitHub/Windows relay."""
import argparse, collections, csv, gzip, hashlib, io, json, os, pathlib, re, subprocess, sys, tarfile
BASE_RECEIVER = "#!/bin/bash\n# Windows Git Bash: apply the approved internal GitHub route on every Git call.\n# Does not depend on hosts/DNS cache edits or require administrator privileges.\nset -euo pipefail\nset -m\numask 077\nroot=${CROUCH_CLOUD_ROOT:-$HOME/Desktop/crouch-cloud-transfer}\nrepo=\"$root/repository\"\nfiles=\"$root/download\"\nurl=${CROUCH_REPO_URL:-https://github.com/hefanshi-rgb/crouch-offline.git}\nmirror=${CROUCH_MIRROR_IP:-172.30.100.20}\nremote_dir=gw18-recount-v1\narchive=crouch_gw18_recount_bundle.tar.gz\narchive_hash=7250b10ce5a8a1cc0f4949c5feffad9ac87a2ca2c5c309bd2e09d1134f932eaf\nmanifest_hash=10d68fbd89371bd2184491b7c26f9280cf4383848516084ef147b400b40988bc\narchive_bytes=2735965\nmax_attempts=${CROUCH_MAX_ATTEMPTS:-20}\nattempt_seconds=${CROUCH_ATTEMPT_SECONDS:-600}\nno_progress_seconds=${CROUCH_NO_PROGRESS_SECONDS:-1800}\nretry_base=${CROUCH_RETRY_BASE_SECONDS:-10}\nretry_max=${CROUCH_RETRY_MAX_SECONDS:-60}\npoll_seconds=${CROUCH_POLL_SECONDS:-1}\nfor value in \"$max_attempts\" \"$attempt_seconds\" \"$no_progress_seconds\" \"$retry_base\" \"$retry_max\" \"$poll_seconds\"; do\n    [[ \"$value\" =~ ^[1-9][0-9]*$ && ${#value} -le 6 ]] || { printf 'Invalid retry setting: %s\\n' \"$value\" >&2; exit 1; }\ndone\n[[ \"$mirror\" =~ ^([0-9]{1,3}\\.){3}[0-9]{1,3}$ ]] || { printf 'Invalid mirror IPv4 address\\n' >&2; exit 1; }\nmkdir -p \"$files\"\nexport GIT_TERMINAL_PROMPT=0 GCM_INTERACTIVE=Never\nunset GIT_SSL_NO_VERIFY\ngit_options=(-c core.autocrlf=false -c protocol.version=2 -c http.version=HTTP/1.1\n    -c http.https://github.com/.proxy= -c http.https://github.com/.sslVerify=true\n    -c http.https://github.com/.curloptResolve=\n    -c \"http.https://github.com/.curloptResolve=github.com:443:$mirror\"\n    -c http.lowSpeedLimit=512 -c http.lowSpeedTime=60)\ncase \"$(uname -s)\" in\n    MINGW*|MSYS*|CYGWIN*) git_options+=(-c http.https://github.com/.sslBackend=schannel);;\nesac\ng() { git \"${git_options[@]}\" \"$@\"; }\nlog() { printf '[%s] %s\\n' \"$(date '+%Y-%m-%d %H:%M:%S')\" \"$*\" | tee -a \"$root/transfer.log\"; }\ndie() { log \"STOP: $*\" >&2; exit 1; }\nactive_pid=\nlock_owned=false\nlock=\"$root/.running\"\nlast_progress=$(date +%s)\nnetwork_shown=0\nstop_active() {\n    local n\n    if [[ -n \"$active_pid\" ]]; then\n        kill -TERM -- \"-$active_pid\" 2>/dev/null || kill -TERM \"$active_pid\" 2>/dev/null || true\n        for n in 1 2 3; do kill -0 -- \"-$active_pid\" 2>/dev/null || break; sleep 1; done\n        kill -KILL -- \"-$active_pid\" 2>/dev/null || true\n        wait \"$active_pid\" 2>/dev/null || true\n        active_pid=\n    fi\n}\ncleanup() {\n    stop_active\n    if [[ \"$lock_owned\" == true ]]; then rm -f \"$lock/pid\"; rmdir \"$lock\" 2>/dev/null || true; fi\n}\ntrap cleanup EXIT\ntrap 'log \"Stopped by Ctrl+C; verified parts are retained.\"; exit 130' INT\ntrap 'log \"Stopped by signal; verified parts are retained.\"; exit 143' TERM\nguard() {\n    [[ ! -e \"$root/STOP\" ]] || die \"STOP file found: $root/STOP. Remove it before resuming.\"\n    (( $(date +%s) - last_progress < no_progress_seconds )) || die \"No verified progress for ${no_progress_seconds}s. Inspect transfer.log and last-network.log.\"\n}\npause_retry() {\n    local seconds=$1 n\n    for ((n=0; n<seconds; n++)); do guard; sleep 1; done\n}\nflush_network_output() {\n    local bytes delta\n    bytes=$(wc -c < \"$root/last-network.log\")\n    delta=$((bytes - network_shown))\n    if (( delta > 0 )); then\n        dd if=\"$root/last-network.log\" bs=1 skip=\"$network_shown\" count=\"$delta\" 2>/dev/null | cat >&2\n        network_shown=$bytes\n    fi\n}\nrun_network() {\n    local input=$1 started status\n    shift\n    guard\n    started=$(date +%s)\n    : > \"$root/last-network.log\"\n    network_shown=0\n    git \"${git_options[@]}\" \"$@\" < \"$input\" > \"$root/last-network.log\" 2>&1 &\n    active_pid=$!\n    while kill -0 \"$active_pid\" 2>/dev/null; do\n        flush_network_output\n        guard\n        if (( $(date +%s) - started >= attempt_seconds )); then\n            stop_active\n            flush_network_output\n            log \"Attempt timed out after ${attempt_seconds}s.\"\n            return 124\n        fi\n        sleep \"$poll_seconds\"\n    done\n    if wait \"$active_pid\"; then status=0; else status=$?; fi\n    active_pid=\n    flush_network_output\n    if (( status != 0 )) && grep -Eiq 'Authentication failed|could not read Username|Repository not found|returned error: (401|403|407)|not our ref|does not allow request|filtering not recognized' \"$root/last-network.log\"; then\n        die 'Repository, permission, or server-capability error; see last-network.log. This requires correction rather than endless retries.'\n    fi\n    return \"$status\"\n}\nretry_network() {\n    local label=$1 input=$2 n delay=$retry_base\n    shift 2\n    for ((n=1; n<=max_attempts; n++)); do\n        guard\n        log \"$label, attempt $n/$max_attempts\"\n        if run_network \"$input\" \"$@\"; then return 0; fi\n        (( n < max_attempts )) || die \"$label failed $max_attempts times. Verified downloads are retained.\"\n        log \"Retrying in ${delay}s.\"\n        pause_retry \"$delay\"\n        delay=$((delay * 2))\n        if (( delay > retry_max )); then delay=$retry_max; fi\n    done\n}\nverified() { [[ -s \"$2\" ]] && printf '%s  %s\\n' \"$1\" \"$2\" | sha256sum -c - >/dev/null 2>&1; }\npublish_desktop() {\n    local desktop=\"$HOME/Desktop/$archive\"\n    if [[ ! -e \"$desktop\" ]]; then\n        local temp\n        temp=$(mktemp \"$HOME/Desktop/.crouch-gw18.XXXXXX\")\n        cp \"$files/$archive\" \"$temp\"\n        mv \"$temp\" \"$desktop\"\n    elif ! verified \"$archive_hash\" \"$desktop\"; then\n        log \"An existing different Desktop file was preserved. Use $files/$archive\"\n        return\n    fi\n    log \"READY ON DESKTOP: $desktop\"\n}\ninstall_shortcut() {\n    case \"$(uname -s)\" in\n        MINGW*|MSYS*|CYGWIN*)\n            local bash_path script_path\n            bash_path=$(cygpath -m \"$BASH\")\n            script_path=$(cygpath -m \"$(cd -- \"$(dirname -- \"${BASH_SOURCE[0]}\")\" && pwd)/$(basename -- \"${BASH_SOURCE[0]}\")\")\n            # Percent signs in a Windows path must be doubled in a batch file.\n            bash_path=${bash_path//%/%%}; script_path=${script_path//%/%%}\n            printf '@echo off\\r\\n\"%s\" --login \"%s\"\\r\\nset \"CROUCH_EXIT_CODE=%%ERRORLEVEL%%\"\\r\\necho.\\r\\npause\\r\\nexit /b %%CROUCH_EXIT_CODE%%\\r\\n' \\\n                \"$bash_path\" \"$script_path\" > \"$HOME/Desktop/crouch_cloud_receive.cmd\"\n            ;;\n    esac\n}\n\nguard\nif ! mkdir \"$lock\" 2>/dev/null; then\n    old_pid=$(cat \"$lock/pid\" 2>/dev/null || true)\n    if [[ \"$old_pid\" =~ ^[0-9]+$ ]] && kill -0 \"$old_pid\" 2>/dev/null; then die \"Another receiver is running: PID $old_pid\"; fi\n    rm -f \"$lock/pid\"\n    rmdir \"$lock\" || die \"Inspect stale lock: $lock\"\n    mkdir \"$lock\"\nfi\nlock_owned=true\nprintf '%s\\n' \"$$\" > \"$lock/pid\"\ninstall_shortcut\nlog \"GitHub route configured for this run: github.com:443 -> $mirror; HTTPS verification enabled.\"\nlog \"Stop: Ctrl+C, or create $root/STOP. Retry limit $max_attempts; no-progress limit ${no_progress_seconds}s.\"\nif verified \"$archive_hash\" \"$files/$archive\"; then\n    gzip -t \"$files/$archive\"\n    publish_desktop\n    log 'Already downloaded and verified; no network transfer needed.'\n    exit 0\nfi\nif [[ ! -d \"$repo/.git\" ]]; then\n    [[ ! -e \"$repo\" ]] || die \"Inspect existing non-repository path: $repo\"\n    git init -q \"$repo\"\n    g -C \"$repo\" remote add origin \"$url\"\nfi\n[[ \"$(g -C \"$repo\" remote get-url origin)\" == \"$url\" ]] || die 'Existing repository has a different origin; preserving it.'\ng -C \"$repo\" config remote.origin.promisor true\ng -C \"$repo\" config remote.origin.partialclonefilter blob:none\nretry_network 'Refreshing repository metadata only' /dev/null -C \"$repo\" fetch --progress --depth=1 --no-tags --filter=blob:none origin main\nsnapshot=$(g -C \"$repo\" rev-parse --verify FETCH_HEAD)\nlog \"Pinned snapshot: $snapshot\"\n\nget_file() {\n    local name=$1 destination=$2 expected=$3 oid\n    oid=$(g -C \"$repo\" rev-parse --verify \"$snapshot:$remote_dir/$name\") || die \"Release path missing: $remote_dir/$name. The internal mirror may not have synchronized yet.\"\n    printf '%s\\n' \"$oid\" > \"$root/object-want.txt\"\n    retry_network \"Fetching $name\" \"$root/object-want.txt\" -C \"$repo\" -c fetch.negotiationAlgorithm=noop fetch --progress --no-tags \\\n        --no-write-fetch-head --recurse-submodules=no --filter=blob:none --stdin origin\n    g -C \"$repo\" cat-file blob \"$oid\" > \"$destination\"\n    verified \"$expected\" \"$destination\" || die \"Checksum mismatch for $name; preserving .partial for inspection.\"\n}\nget_file PARTS_SHA256SUMS \"$files/PARTS_SHA256SUMS.partial\" \"$manifest_hash\"\nmv -f \"$files/PARTS_SHA256SUMS.partial\" \"$files/PARTS_SHA256SUMS\"\ntotal=0\nwhile read -r hash name extra; do\n    [[ \"$hash\" =~ ^[0-9a-f]{64}$ && \"$name\" =~ ^crouch_gw18_recount_bundle\\.tar\\.gz\\.part\\.[0-9]{3}$ && -z \"${extra:-}\" ]] || die 'Invalid part manifest'\n    total=$((total + 1))\ndone < \"$files/PARTS_SHA256SUMS\"\n[[ \"$total\" == 2 ]] || die 'Expected exactly two parts for this release'\ni=0\nwhile read -r hash name; do\n    guard\n    i=$((i + 1))\n    if verified \"$hash\" \"$files/$name\"; then\n        log \"[$i/$total] SKIP verified $name\"\n    else\n        log \"[$i/$total] DOWNLOAD $name\"\n        get_file \"$name\" \"$files/$name.partial\" \"$hash\"\n        (( $(wc -c < \"$files/$name.partial\") <= 2097152 )) || die 'Part exceeds 2 MiB'\n        mv -f \"$files/$name.partial\" \"$files/$name\"\n        log \"[$i/$total] VERIFIED $name\"\n    fi\n    last_progress=$(date +%s)\ndone < \"$files/PARTS_SHA256SUMS\"\n(\n    while read -r hash name; do guard; cat \"$files/$name\"; done < \"$files/PARTS_SHA256SUMS\"\n) > \"$files/$archive.partial\"\nverified \"$archive_hash\" \"$files/$archive.partial\" || die 'Reassembled archive checksum mismatch'\n[[ \"$(wc -c < \"$files/$archive.partial\" | tr -d ' ')\" == \"$archive_bytes\" ]] || die 'Archive size mismatch'\ngzip -t \"$files/$archive.partial\"\nmv -f \"$files/$archive.partial\" \"$files/$archive\"\nprintf '%s  %s\\n' \"$archive_hash\" \"$archive\" > \"$files/ARCHIVE_SHA256SUMS\"\npublish_desktop\nlog \"DOWNLOAD COMPLETE: $files/$archive\"\nprintf '\\nUpload the verified archive to the cluster Crouch/ directory.\\n'\n"
BASE_INSTALLER = "#!/bin/bash\n# Paste this complete block into Windows Git Bash once.\n(\nset -euo pipefail\nexport GIT_TERMINAL_PROMPT=0 GCM_INTERACTIVE=Never\nunset GIT_SSL_NO_VERIFY\nreceiver=\"$HOME/Desktop/crouch_cloud_receive.sh\"\nscript_hash=8f3597307326a6aa2a4a85046e02d38e375535d4650afaa19e3e162c2538947e\nnet=(-c http.https://github.com/.curloptResolve=\n     -c http.https://github.com/.curloptResolve=github.com:443:172.30.100.20\n     -c http.https://github.com/.proxy=\n     -c http.https://github.com/.sslBackend=schannel\n     -c http.https://github.com/.sslVerify=true\n     -c http.version=HTTP/1.1 -c protocol.version=2\n     -c http.lowSpeedLimit=512 -c http.lowSpeedTime=60)\ng() { git \"${net[@]}\" \"$@\"; }\nrepo=\"$HOME/Desktop/crouch-cloud-transfer/repository\"\nif [[ -s \"$receiver\" ]] && printf '%s  %s\\n' \"$script_hash\" \"$receiver\" | sha256sum -c -; then\n    bash \"$receiver\"\n    exit\nfi\nmkdir -p \"$HOME/Desktop/crouch-cloud-transfer\"\nif [[ ! -d \"$repo/.git\" ]]; then\n    [[ ! -e \"$repo\" ]] || { printf 'Inspect existing path: %s\\n' \"$repo\" >&2; exit 1; }\n    git init -q \"$repo\"\n    g -C \"$repo\" remote add origin https://github.com/hefanshi-rgb/crouch-offline.git\nfi\n[[ \"$(g -C \"$repo\" remote get-url origin)\" == https://github.com/hefanshi-rgb/crouch-offline.git ]] || exit 1\ng -C \"$repo\" config remote.origin.promisor true\ng -C \"$repo\" config remote.origin.partialclonefilter blob:none\nfor attempt in {1..10}; do\n    printf 'Installing cloud receiver: attempt %s/10\\n' \"$attempt\"\n    if g -C \"$repo\" fetch --progress --depth=1 --no-tags --filter=blob:none origin main &&\n       g -C \"$repo\" show FETCH_HEAD:cloud-transfer/crouch_cloud_receive.sh > \"$receiver.partial\" &&\n       printf '%s  %s\\n' \"$script_hash\" \"$receiver.partial\" | sha256sum -c -; then\n        mv -f \"$receiver.partial\" \"$receiver\"\n        bash \"$receiver\"\n        exit\n    fi\n    sleep 10\ndone\nprintf 'Installation stopped after 10 attempts; existing downloads were retained.\\n' >&2\nexit 1\n)\n"
CLUSTER_SCRIPT = "#!/bin/bash\n# Metadata-only validation. Counts and all genes remain unchanged.\nset -Eeuo pipefail\numask 077\nBASE=/public4/usersdir/guojunping/guojunping_2026-11-08_001/upload/Crouch\nSELF=$(cd \"$(dirname \"${BASH_SOURCE[0]}\")\" && pwd -P)/$(basename \"${BASH_SOURCE[0]}\")\nif [[ \"${1:-}\" != --worker ]]; then\n    mode=${1:-inspect}; mapping=${2:-}\n    [[ \"$mode\" == inspect || \"$mode\" == compare ]] || { echo 'Usage: bash crouch_author_meta_check.sh inspect | compare REVIEWED_MAPPING.tsv'; exit 1; }\n    if [[ \"$mode\" == compare ]]; then\n        [[ -s \"$mapping\" ]] || { echo 'Provide a reviewed mapping file'; exit 1; }\n        mapping=$(cd \"$(dirname \"$mapping\")\" && pwd -P)/$(basename \"$mapping\")\n    fi\n    [[ -s \"$BASE/author_meta_all/meta.tsv\" ]] || { echo 'Missing author_meta_all/meta.tsv'; exit 1; }\n    if ! type module >/dev/null 2>&1; then\n        for init in /etc/profile.d/modules.sh /usr/share/Modules/init/bash /usr/share/lmod/lmod/init/bash; do\n            if [[ -r \"$init\" ]]; then set +u; source \"$init\"; set -u; break; fi\n        done\n    fi\n    set +u\n    module use /public/software/modules\n    module load compiler/gcc/7.4.0 system/R/4.3.1\n    set -u\n    lib=$(gfortran -print-file-name=libgfortran.so.4)\n    [[ \"$lib\" == /* && -r \"$lib\" ]] || { echo 'GCC runtime missing'; exit 1; }\n    export LD_LIBRARY_PATH=\"${lib%/*}${LD_LIBRARY_PATH:+:$LD_LIBRARY_PATH}\"\n    AUTHOR_META_R=$(command -v Rscript); export AUTHOR_META_R\n    mkdir -p \"$BASE/logs\"\n    reply=$(sbatch --parsable --export=ALL -p bigmem --nodelist=comput159 \\\n        -N 1 -n 1 -c 2 --mem=32G -t 02:00:00 --job-name=\"gw18-meta-$mode\" \\\n        --chdir=\"$BASE\" --output=\"$BASE/logs/gw18-meta-$mode-%j.log\" \"$SELF\" --worker \"$mode\" \"$mapping\")\n    job=${reply%%;*}\n    [[ \"$job\" =~ ^[0-9]+$ ]] || { echo \"$reply\"; exit 1; }\n    printf 'Job=%s\\nLog=%s/logs/gw18-meta-%s-%s.log\\nResult=%s/recount_slurm/GW18/meta_%s_%s\\n' \"$job\" \"$BASE\" \"$mode\" \"$job\" \"$BASE\" \"$mode\" \"$job\"\n    exit 0\nfi\n: \"${SLURM_JOB_ID:?Submit through the launcher}\"\nmode=${2:?}; mapping=${3:-}\nOUT=\"$BASE/recount_slurm/GW18/meta_${mode}_${SLURM_JOB_ID}\"\nmkdir \"$OUT\"\ncp \"$SELF\" \"$OUT/submitted_script.sh\"\nexport TZ=UTC OMP_NUM_THREADS=1 OPENBLAS_NUM_THREADS=1\nexport R_LIBS=\"$BASE/software/r-libraries/R-4.3.1-Matrix-1.6.0${R_LIBS:+:$R_LIBS}\"\nexport R_LIBS_USER=\"$R_LIBS\"\nsed -n '/^# BEGIN_R$/,/^# END_R$/p' \"$SELF\" > \"$OUT/meta_check.R\"\n\"$AUTHOR_META_R\" --vanilla \"$OUT/meta_check.R\" \"$BASE\" \"$BASE/author_meta_all/meta.tsv\" \"$mode\" \"$mapping\" \"$OUT\"\ntouch \"$OUT/COMPLETE\"\nprintf '\\nSUCCESS: %s\\n' \"$OUT\"\ncat \"$OUT/report.txt\"\nexit 0\n: <<'R_EMBEDDED'\n# BEGIN_R\nsuppressPackageStartupMessages(library(Matrix))\na <- commandArgs(TRUE); stopifnot(length(a)==5L)\nbase<-a[1]; path<-a[2]; mode<-a[3]; mapping.path<-a[4]; out<-a[5]\nwrite.tsv<-function(x,p) write.table(x,p,sep='\\t',quote=FALSE,row.names=FALSE,na='NA')\nallmeta<-read.delim(path,check.names=FALSE,stringsAsFactors=FALSE,quote='',comment.char='')\nstopifnot(all(c('cellId','age') %in% names(allmeta)),!anyDuplicated(allmeta$cellId),\n          all(!is.na(allmeta$cellId)&nzchar(allmeta$cellId)))\nallmeta$age<-trimws(as.character(allmeta$age))\ninvcols<-intersect(c('age','sample','area'),names(allmeta))\ninventory<-as.data.frame(table(allmeta[,invcols,drop=FALSE]),stringsAsFactors=FALSE)\ninventory<-inventory[inventory$Freq>0,,drop=FALSE]\nwrite.tsv(inventory,file.path(out,'all_sample_inventory.tsv'))\nmeta<-allmeta[toupper(allmeta$age)=='GW18' & !is.na(allmeta$age),,drop=FALSE]\nif(!nrow(meta)) stop('No age=GW18 rows; inspect age labels')\nmetrics<-intersect(c('ncount_rna','nCount_RNA','nfeature_rna','nFeature_RNA','percent_mito','percent_ribo'),names(allmeta))\naudit<-list()\nfor(scope in c('all','GW18')) for(field in metrics) {\n    dat<-if(scope=='all') allmeta else meta\n    z<-suppressWarnings(as.numeric(as.character(dat[[field]]))); finite<-is.finite(z)\n    q<-if(any(finite)) quantile(z[finite],c(0,.25,.5,.75,1),names=FALSE) else rep(NA_real_,5)\n    audit[[length(audit)+1L]]<-data.frame(scope=scope,field=field,rows=length(z),\n       missing_or_nonfinite=sum(!finite),noninteger=sum(abs(z[finite]-round(z[finite]))>1e-6),\n       minimum=q[1],q25=q[2],median=q[3],q75=q[4],maximum=q[5])\n}\nwrite.tsv(do.call(rbind,audit),file.path(out,'author_QC_column_audit.tsv'))\nparts<-regmatches(meta$cellId,regexec('^(.*?)([ACGT]{16})(?:-([1-9][0-9]*))?$',meta$cellId,perl=TRUE))\nif(any(lengths(parts)<3L)) stop('Unexpected author cell IDs; explicit parsing required')\nprefix<-vapply(parts,function(z) z[2],''); cb<-vapply(parts,function(z) z[3],'')\ngem<-vapply(parts,function(z) if(length(z)>=4L) z[4] else '','')\nfull<-readRDS(file.path(base,'recount_slurm/GW18/full_1713860/GW18_for_qc.rds'))\nactual<-full$cell_metadata; full<-NULL; gc(FALSE)\nactual$gem<-sub('.*-','',actual$CB); actual$sequence<-sub('-[1-9][0-9]*$','',actual$CB)\nstopifnot(!anyDuplicated(paste(actual$library,actual$CB,sep='|')))\nqcdir<-file.path(base,'recount_slurm/GW18/qc_1717229')\nstopifnot(file.exists(file.path(qcdir,'COMPLETE')))\ncalled<-readRDS(file.path(qcdir,'GW18_cellcalled_for_qc.rds'))$cell_metadata$cell_id\ncandidate<-readRDS(file.path(qcdir,'GW18_qc_candidate_for_qc.rds'))\nqc<-candidate$cell_metadata$cell_id\nactual$called<-actual$cell_id %in% called; actual$qc<-actual$cell_id %in% qc\nag<-split(seq_len(nrow(actual)),paste(actual$library,actual$gem,sep='|GEM='))\nrows<-list(); prefix.info<-list()\nfor(p in sort(unique(prefix))) {\n    jj<-which(prefix==p)\n    z<-data.frame(author_prefix=p,cells=length(jj))\n    for(f in intersect(c('sample','area','cell_type'),names(meta)))\n        z[[f]]<-paste(sort(unique(as.character(meta[jj,f]))),collapse='; ')\n    prefix.info[[p]]<-z\n    for(ix in ag) {\n        thisgem<-actual$gem[ix[1]]; mi<-match(cb[jj],actual$sequence[ix])\n        ok<-(!nzchar(gem[jj])|gem[jj]==thisgem)&!is.na(mi); hit<-ix[mi[ok]]\n        rows[[length(rows)+1L]]<-data.frame(author_prefix=p,author_cells=length(jj),\n            recount_library=actual$library[ix[1]],recount_gem=thisgem,\n            raw_matches=sum(ok),raw_fraction=mean(ok),called_matches=sum(actual$called[hit]),\n            qc_matches=sum(actual$qc[hit]),qc_fraction=sum(actual$qc[hit])/length(jj))\n    }\n}\noverlap<-do.call(rbind,rows)\noverlap<-overlap[order(overlap$author_prefix,-overlap$raw_fraction),]\nwrite.tsv(overlap,file.path(out,'prefix_library_overlap.tsv'))\nwrite.tsv(do.call(rbind,prefix.info),file.path(out,'author_prefix_inventory.tsv'))\nwrite.tsv(data.frame(author_prefix=sort(unique(prefix)),recount_library='',recount_gem=''),\n          file.path(out,'library_mapping_to_review.tsv'))\nwrite.tsv(meta,file.path(out,'author_GW18_meta.tsv'))\nreport<-c('Metadata-only comparison: no gene-expression matrix was supplied.',\n    paste('All author metadata cells:',nrow(allmeta)),paste('Author GW18 cells:',nrow(meta)),\n    paste('Our called cells:',length(called)),paste('Our QC candidates:',length(qc)),\n    'Mapping candidates below are not adopted automatically; inspect labels and barcode overlaps.',\n    capture.output(print(overlap,row.names=FALSE,digits=4)),\n    '\\nAuthor prefix labels:',capture.output(print(do.call(rbind,prefix.info),row.names=FALSE)),\n    '\\nAuthor QC-column audit (GW18):',\n    capture.output(print(do.call(rbind,audit)[do.call(rbind,audit)$scope=='GW18',],row.names=FALSE,digits=5)))\nif(mode=='compare') {\n    mapping<-read.delim(mapping.path,check.names=FALSE,stringsAsFactors=FALSE,\n        colClasses='character',quote='',comment.char='',na.strings='')\n    req<-c('author_prefix','recount_library','recount_gem')\n    stopifnot(all(req %in% names(mapping)),!anyNA(mapping[,req]),!anyDuplicated(mapping$author_prefix))\n    mm<-match(prefix,mapping$author_prefix)\n    if(anyNA(mm)) stop('Some author prefixes have no reviewed mapping')\n    lib<-mapping$recount_library[mm]; mg<-mapping$recount_gem[mm]\n    stopifnot(all(grepl('^[1-9][0-9]*$',mg)),all(!nzchar(gem)|gem==mg))\n    stopifnot(all(paste(lib,mg,sep='|GEM=') %in% names(ag)))\n    keys<-paste(lib,paste0(cb,'-',mg),sep='|')\n    if(anyDuplicated(keys)) stop('Mapping merges different author cells; review library identities')\n    ri<-match(keys,paste(actual$library,actual$CB,sep='|'))\n    if(!any(!is.na(ri))) stop('No cell matches; review mapping')\n    comparison<-data.frame(author_cell=meta$cellId,author_prefix=prefix,recount_library=lib,\n        recount_gem=mg,CB=paste0(cb,'-',mg),raw_match=!is.na(ri),\n        called_match=!is.na(ri)&actual$called[ri],qc_match=!is.na(ri)&actual$qc[ri],\n        recount_cell=actual$cell_id[ri],recount_UMIs=actual$nCount_RNA[ri],\n        recount_genes=actual$nFeature_RNA[ri],recount_percent_mito=actual$percent_mito[ri])\n    for(f in metrics) comparison[[paste0('author_',f)]]<-meta[[f]]\n    write.tsv(comparison,file.path(out,'cell_metadata_comparison.tsv'))\n    mi<-match(candidate$cell_metadata$cell_id,comparison$recount_cell)\n    original.names<-names(candidate$cell_metadata)\n    if(any(paste0('author_',names(meta)) %in% original.names)) stop('Author annotation columns already exist')\n    candidate$cell_metadata$author_match<-!is.na(mi)\n    for(f in names(meta)) candidate$cell_metadata[[paste0('author_',f)]]<-meta[[f]][mi]\n    candidate$provenance$author_metadata<-list(source=path,source_MD5=unname(tools::md5sum(path)),\n        mapping=mapping,comparison='Cell identity, annotation and QC metrics only; no gene-expression validation',\n        counts_changed=FALSE,features_removed=FALSE)\n    saveRDS(candidate,file.path(out,'GW18_qc_candidate_with_author_metadata.rds'),compress='gzip')\n    corr<-list()\n    for(l in sort(unique(lib))) for(f in intersect(c('ncount_rna','nCount_RNA','nfeature_rna','nFeature_RNA'),metrics)) {\n        ix<-which(lib==l & comparison$qc_match)\n        av<-suppressWarnings(as.numeric(as.character(meta[[f]][ix])))\n        own<-if(grepl('feature',f,ignore.case=TRUE)) comparison$recount_genes[ix] else comparison$recount_UMIs[ix]\n        ok<-is.finite(av)&is.finite(own)\n        rho<-if(sum(ok)>=3 && sd(av[ok])>0 && sd(own[ok])>0) cor(av[ok],own[ok],method='spearman') else NA_real_\n        corr[[length(corr)+1L]]<-data.frame(library=l,author_field=f,cells=sum(ok),spearman_QC_metric=rho)\n    }\n    write.tsv(do.call(rbind,corr),file.path(out,'QC_metric_correlations.tsv'))\n    coverage<-do.call(rbind,lapply(sort(unique(lib)),function(l){ii<-which(lib==l)\n        data.frame(library=l,author_cells=length(ii),raw_matches=sum(comparison$raw_match[ii]),\n            called_matches=sum(comparison$called_match[ii]),qc_matches=sum(comparison$qc_match[ii]))}))\n    write.tsv(coverage,file.path(out,'author_cell_coverage.tsv'))\n    report<-c(report,'\\nREVIEWED MAPPING APPLIED:',capture.output(print(coverage,row.names=FALSE)),\n       paste('QC candidate cells with author annotation:',sum(!is.na(mi)),'/',length(mi)),\n       'All QC candidate cells and all original features are retained. Counts were not normalized or changed.',\n       'QC-metric correlation is not gene-expression concordance or proof of exact count recovery.')\n}\nwriteLines(report,file.path(out,'report.txt'))\nwriteLines(capture.output(sessionInfo()),file.path(out,'R_sessionInfo.txt'))\n# END_R\nR_EMBEDDED\n"

def sha(b): return hashlib.sha256(b).hexdigest()
def replace_one(text, old, new):
    if text.count(old) != 1: raise RuntimeError('Unexpected receiver template: '+old)
    return text.replace(old, new)
def receiver_for(archive, digest, manifest_digest, size, total):
    s=BASE_RECEIVER.replace('crouch-cloud-transfer','crouch-author-meta-transfer')
    s=s.replace('crouch_cloud_receive.cmd','crouch_author_meta_receive.cmd')
    s=s.replace('.crouch-gw18.XXXXXX','.crouch-author-meta.XXXXXX')
    s=replace_one(s,'remote_dir=gw18-recount-v1','remote_dir=author-meta-v1')
    s=replace_one(s,'archive=crouch_gw18_recount_bundle.tar.gz','archive='+archive)
    s,n=re.subn(r'^archive_hash=[0-9a-f]{64}$','archive_hash='+digest,s,flags=re.M); assert n==1
    s,n=re.subn(r'^manifest_hash=[0-9a-f]{64}$','manifest_hash='+manifest_digest,s,flags=re.M); assert n==1
    s,n=re.subn(r'^archive_bytes=\d+$','archive_bytes='+str(size),s,flags=re.M); assert n==1
    s=replace_one(s,r'^crouch_gw18_recount_bundle\.tar\.gz\.part\.[0-9]{3}$',re.escape(archive)+r'\.part\.[0-9]{5}$')
    s=replace_one(s,'[[ "$total" == 2 ]]', '[[ "$total" == '+str(total)+' ]]')
    s=s.replace('Expected exactly two parts for this release','Unexpected metadata part count')
    s=replace_one(s,'    log "READY ON DESKTOP: $desktop"',
        '    printf \'%s  %s\\n\' "$archive_hash" "$archive" > "$HOME/Desktop/crouch_author_meta_SHA256SUMS"\n    log "READY ON DESKTOP: $desktop"')
    s=s.replace('Upload the verified archive to the cluster Crouch/ directory.',
        'Upload the archive AND crouch_author_meta_SHA256SUMS from Desktop to the cluster Crouch/ directory.')
    return s

def main():
    ap=argparse.ArgumentParser(description=__doc__)
    ap.add_argument('--meta',type=pathlib.Path)
    ap.add_argument('--repo',type=pathlib.Path,default=pathlib.Path.home()/'Documents/GitHub/crouch-offline')
    ap.add_argument('--output',type=pathlib.Path,default=pathlib.Path.home()/'Desktop/crouch-author-meta-transfer')
    a=ap.parse_args()
    if a.meta is None:
        chosen=subprocess.run(['osascript','-e','POSIX path of (choose file with prompt "选择作者完整的 meta.tsv（不要选择 matrix 或 RDS）")'],check=True,capture_output=True,text=True).stdout.rstrip('\r\n')
        a.meta=pathlib.Path(chosen)
    if not (a.repo/'.git').exists(): raise SystemExit('Git repository missing: '+str(a.repo))
    # Read and validate the selected metadata file only. No expression matrix is accessed.
    with a.meta.open('r',encoding='utf-8-sig',newline='') as f:
        reader=csv.DictReader(f,delimiter='\t')
        fields=reader.fieldnames or []
        if not {'cellId','age'}.issubset(fields): raise SystemExit('Expected cellId and age columns; choose the actual meta.tsv')
        cells=set(); ages=collections.Counter(); count=0
        for row in reader:
            cell=row.get('cellId','')
            if not cell or cell in cells: raise SystemExit('Missing or duplicate cellId; resolve metadata before transfer')
            cells.add(cell); ages[row.get('age','').strip()]+=1; count+=1
    if not count: raise SystemExit('Empty metadata')
    stage=a.output; release=a.repo/'author-meta-v1'; cloud=a.repo/'cloud-transfer'
    if release.exists(): raise SystemExit('author-meta-v1 already exists. Existing release preserved; do not regenerate a different payload under the same name.')
    if stage.exists(): raise SystemExit('Output folder already exists: '+str(stage)+'. Existing transfer preserved.')
    stage.mkdir(parents=True)
    release.mkdir(); cloud.mkdir(exist_ok=True)
    archive='crouch_author_meta.tar.gz'
    meta_bytes=a.meta.read_bytes()
    info={'cells':count,'columns':fields,'age_counts':dict(ages),
          'scope':'Complete author metadata, all samples and ages; no expression matrix',
          'meta_SHA256':sha(meta_bytes)}
    payload={'meta.tsv':meta_bytes,'crouch_author_meta_check.sh':CLUSTER_SCRIPT.encode(),
             'SOURCE_INFO.json':(json.dumps(info,ensure_ascii=False,indent=2)+'\n').encode()}
    payload['AUTHOR_META_SHA256SUMS']=''.join(sha(v)+'  '+k+'\n' for k,v in payload.items()).encode()
    with tarfile.open(stage/archive,'w:gz',compresslevel=1,format=tarfile.USTAR_FORMAT) as tf:
        for name,data in payload.items():
            ti=tarfile.TarInfo('author_meta_all/'+name); ti.size=len(data); ti.mode=0o644
            tf.addfile(ti,io.BytesIO(data))
    part_lines=[]; whole=hashlib.sha256(); total=0
    with (stage/archive).open('rb') as f:
        while True:
            chunk=f.read(2*1024*1024)
            if not chunk: break
            total+=1; whole.update(chunk)
            name=archive+'.part.'+str(total).zfill(5)
            (release/name).write_bytes(chunk); part_lines.append(sha(chunk)+'  '+name+'\n')
    manifest=''.join(part_lines).encode(); (release/'PARTS_SHA256SUMS').write_bytes(manifest)
    digest=whole.hexdigest(); size=(stage/archive).stat().st_size
    (release/'ARCHIVE_SHA256SUMS').write_text(digest+'  '+archive+'\n',encoding='utf-8')
    (stage/'crouch_author_meta_SHA256SUMS').write_text(digest+'  '+archive+'\n',encoding='utf-8')
    receiver=receiver_for(archive,digest,sha(manifest),size,total)
    (cloud/'crouch_author_meta_receive.sh').write_text(receiver,encoding='utf-8')
    installer=BASE_INSTALLER.replace('crouch_cloud_receive.sh','crouch_author_meta_receive.sh').replace('crouch-cloud-transfer','crouch-author-meta-transfer')
    installer,n=re.subn(r'^script_hash=[0-9a-f]{64}$','script_hash='+sha(receiver.encode()),installer,flags=re.M); assert n==1
    (stage/'Windows_Git_Bash.txt').write_text(installer,encoding='utf-8')
    attrs=a.repo/'.gitattributes'
    rule='author-meta-v1/*.part.* -text'
    old=attrs.read_text(encoding='utf-8') if attrs.exists() else ''
    if rule not in old.splitlines(): attrs.write_text(old+('' if not old or old.endswith('\n') else '\n')+rule+'\n',encoding='utf-8')
    (release/'TRANSFER_INFO.json').write_text(json.dumps({'archive':archive,'SHA256':digest,'bytes':size,'parts':total,**info},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print('Complete metadata rows:',count)
    print('Age counts:',dict(ages))
    print('Metadata bytes:',len(meta_bytes),'Archive bytes:',size,'2 MiB parts:',total)
    print('Ready in GitHub Desktop: commit ONLY author-meta-v1/, cloud-transfer/crouch_author_meta_receive.sh and .gitattributes, then Push origin.')
    print('After pushing, copy this text into Windows Git Bash:',stage/'Windows_Git_Bash.txt')
    print('Source meta.tsv was read without modification. No matrix or RDS was read.')

if __name__=='__main__': main()
